// Smooth speed handoff, centered on the last panel reaching the top.
releaseEasePx: 250,

// Values are PERCENTAGES of each picture's own height.

// Finish local actor travel BEFORE the common release begins.
// Use the actual final panel offset (including its CSS translateY).
const releaseHalf = noMotion ? 0 : SETTINGS.releaseEasePx / 2;
const storyDistance = Math.max(1, lastTop - rect.top + stickyTop - releaseHalf);

edits.from:
// Release only after the final section has arrived at the top edge.
// Match scroll 1:1 instead of abruptly switching sticky -> relative.

// Smooth the transition from sticky (stationary) to document scrolling.
// The first 180px accelerate progressively instead of switching to 1:1
// movement in a single frame. Above the threshold, motion is exactly 1:1.
const rawExitPx = wide.matches ? Math.max(0, -lastTop) : 0;
const releaseEasePx = 250; // EDIT: 120 = shorter, 240 = softer/longer
const exitProgress = clamp01(rawExitPx / Math.max(1, releaseEasePx));
const exitPx = rawExitPx * smooth(exitProgress);

edits.to:
// Integral of smoothstep SPEED, not displacement * smoothstep.
// Across [-width/2, width/2], speed rises from 0 to 1 and never
// exceeds page speed. Both position and speed meet natural scroll.
const rawExitPx = wide.matches ? -lastTop : 0;
const releaseWidth = Math.max(1, SETTINGS.releaseEasePx);
const exitProgress = clamp01((rawExitPx + releaseHalf) / releaseWidth);
const exitPx = !wide.matches ? 0 : noMotion ? Math.max(0, rawExitPx)
  : rawExitPx >= releaseHalf ? rawExitPx
  : releaseWidth * (exitProgress ** 3 - 0.5 * exitProgress ** 4);

// At document scroll=0 CSS and JS both use startY. A short hero must
// not make the entrance partly complete as soon as deferred JS loads.
const sceneDocumentTop = rect.top + window.scrollY;
const entranceStart = Math.min(viewport * SETTINGS.entrance.startAtViewport, sceneDocumentTop);
